// Generated by build.rs; clippy is exempted for generated code only.
#[allow(clippy::all)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/svg_builder.rs"));
    include!(concat!(env!("OUT_DIR"), "/svg_builder.serde.rs"));
}
pub use generated::*;

/// `parameters.proto` as a `FileDescriptorSet`, for consumers that walk the schema at runtime.
pub const DESCRIPTOR: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/descriptor.bin"));

use crate::Error;
use crate::blueprint::style::MATRIX_COLOR;
use crate::color::{hex_rgb, hex_rgba};
use crate::mood::Mood;
use crate::zine::style::SPOT;

pub fn parse(text: &str) -> Result<Parameters, serde_json::Error> {
    serde_json::from_str(text)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Glyph {
    Hexatri { rotate: bool },
    Ship,
    Punk(PunkLook),
}

/// A zine head's gear and how it turns, and how the head moves to the beat.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rig {
    pub gear: rider::Gear,
    pub ccw: bool,
    /// turns a minute; 0 = still
    pub rpm: u32,
    pub motion: rider::Motion,
    /// beats a minute, for every head animation
    pub bpm: u32,
}

fn rig_of(r: Option<&Rider>) -> Rig {
    let r = r.cloned().unwrap_or_default();
    Rig {
        gear: r.gear(),
        ccw: r.counter_clockwise,
        rpm: r.spin_rpm.unwrap_or(8),
        motion: r.motion(),
        bpm: if r.bpm == 0 { 96 } else { r.bpm },
    }
}

/// The punk's rig and which parts of its head move. Not `Punk`: that is the config message.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PunkLook {
    pub rig: Rig,
    pub crest_wave: bool,
    pub rainbow_flow: bool,
    pub chatter: bool,
    pub eye_pop: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ground {
    Trihex {
        motion: trihex::Motion,
        image: trihex::Image,
    },
    Summit {
        snow: Snow,
    },
    Treeline {
        snow: Snow,
    },
    Halfpipe {
        snow: Snow,
    },
}

#[derive(Debug, Clone, PartialEq)]
pub struct Rain {
    pub angle: f64,
    pub color: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Scene {
    pub seed: u32,
    pub ground: Ground,
    pub glyph: Glyph,
    pub overlay: Option<Rain>,
    /// lowercase `#rrggbb`: the one ink every zine item prints in
    pub spot: String,
}

impl Scene {
    /// True when the ground, the glyph or the overlay belongs to `mood`, i.e. the page needs that
    /// mood's defs and CSS. Distinct from `mood::MOODS`, which says which moods an item is offered in.
    pub fn uses(&self, mood: Mood) -> bool {
        let ground = match self.ground {
            Ground::Trihex { .. } => Mood::Blueprint,
            Ground::Summit { .. } | Ground::Treeline { .. } | Ground::Halfpipe { .. } => Mood::Zine,
        };
        let glyph = match self.glyph {
            Glyph::Hexatri { .. } | Glyph::Ship => Mood::Blueprint,
            Glyph::Punk(_) => Mood::Zine,
        };
        let overlay = self.overlay.as_ref().map(|Rain { .. }| Mood::Blueprint);
        [Some(ground), Some(glyph), overlay].contains(&Some(mood))
    }

    /// Lowercase vocabulary that names the output files. Trihex keeps its legacy one (STARFIELD is `space`).
    pub fn slug(&self) -> String {
        let (fg, icon) = match self.glyph {
            Glyph::Hexatri { rotate: true } => ("rotate", "hexatri"),
            Glyph::Hexatri { rotate: false } => ("static", "hexatri"),
            Glyph::Ship => ("static", "ship"),
            Glyph::Punk(PunkLook {
                rig: Rig { rpm: 0, .. },
                ..
            }) => ("still", "punk"),
            Glyph::Punk(_) => ("spin", "punk"),
        };
        let overlay = if self.overlay.is_some() {
            "matrix"
        } else {
            "none"
        };
        match self.ground {
            Ground::Trihex { motion, image } => {
                let motion = match motion {
                    trihex::Motion::Static => "static",
                    trihex::Motion::Scan => "scan",
                    trihex::Motion::Lights => "lights",
                    trihex::Motion::Closeopen => "closeopen",
                };
                let image = match image {
                    trihex::Image::None => "none",
                    trihex::Image::Starfield => "space",
                };
                format!("{motion}-{fg}-{icon}-{image}-{overlay}")
            }
            Ground::Summit { snow } | Ground::Treeline { snow } | Ground::Halfpipe { snow } => {
                let name = match self.ground {
                    Ground::Summit { .. } => "summit",
                    Ground::Treeline { .. } => "treeline",
                    _ => "halfpipe",
                };
                let snow = match snow {
                    Snow::Flurry => "flurry",
                    Snow::NoSnow => "nosnow",
                    Snow::Blizzard => "blizzard",
                };
                format!("{name}-{snow}-{fg}-{icon}-{overlay}")
            }
        }
    }
}

/// An unset ground is trihex at its defaults. Reads no string, so `validate` can call it too.
fn ground_of(p: &Parameters) -> Ground {
    let trihex = |t: &Trihex| Ground::Trihex {
        motion: t.motion(),
        image: t.image(),
    };
    match p.background.as_ref().and_then(|b| b.ground.as_ref()) {
        Some(background::Ground::Trihex(t)) => trihex(t),
        Some(background::Ground::Summit(s)) => Ground::Summit { snow: s.snow() },
        Some(background::Ground::Treeline(t)) => Ground::Treeline { snow: t.snow() },
        Some(background::Ground::Halfpipe(h)) => Ground::Halfpipe { snow: h.snow() },
        None => trihex(&Trihex::default()),
    }
}

fn spot_of(p: &Parameters) -> &str {
    p.zine.as_ref().map_or("", |z| z.spot.as_str())
}

pub fn resolve(p: &Parameters) -> Scene {
    let glyph = match p.icon.as_ref().and_then(|i| i.glyph.as_ref()) {
        Some(icon::Glyph::Ship(_)) => Glyph::Ship,
        Some(icon::Glyph::Hexatri(h)) => Glyph::Hexatri {
            rotate: h.motion() == hexatri::Motion::Rotate,
        },
        Some(icon::Glyph::Punk(p)) => Glyph::Punk(PunkLook {
            rig: rig_of(p.rider.as_ref()),
            crest_wave: p.crest_wave,
            rainbow_flow: p.rainbow_flow,
            chatter: p.chatter,
            eye_pop: p.eyes() == punk::Eyes::Pop,
        }),
        None => Glyph::Hexatri { rotate: true },
    };
    let overlay =
        p.overlay
            .as_ref()
            .and_then(|o| o.layer.as_ref())
            .map(|overlay::Layer::Matrix(m)| Rain {
                angle: m.angle,
                color: if m.color.is_empty() {
                    MATRIX_COLOR.to_string()
                } else {
                    m.color.clone()
                },
            });
    let spot = match spot_of(p) {
        "" => SPOT.to_string(),
        s => hex_rgb(s).expect("validate() already accepted zine.spot"),
    };
    Scene {
        seed: p.seed,
        ground: ground_of(p),
        glyph,
        overlay,
        spot,
    }
}

/// The rules parameters.proto cannot state. Prefer moving a field over adding a check here.
pub fn validate(p: &Parameters) -> Result<(), Error> {
    if ground_of(p)
        == (Ground::Trihex {
            motion: trihex::Motion::Closeopen,
            image: trihex::Image::None,
        })
    {
        return Err(Error::Invalid(
            "background.trihex.motion CLOSEOPEN has nothing to reveal with background.trihex.image NONE \
             (its hexagons open onto an image); set image STARFIELD, or motion LIGHTS"
                .into(),
        ));
    }
    if let Some(overlay::Layer::Matrix(m)) = p.overlay.as_ref().and_then(|o| o.layer.as_ref()) {
        if !(0.0..=360.0).contains(&m.angle) {
            return Err(Error::Invalid(format!(
                "overlay.matrix.angle {} is outside 0-360 \
                 (0 = falling down, increasing clockwise)",
                crate::geom::fmt(m.angle)
            )));
        }
        let color = if m.color.is_empty() {
            MATRIX_COLOR
        } else {
            &m.color
        };
        hex_rgba(color).map_err(|e| Error::Invalid(format!("overlay.matrix.color: {e}")))?;
    }
    if let Some(icon::Glyph::Punk(punk)) = p.icon.as_ref().and_then(|i| i.glyph.as_ref()) {
        let Rig { rpm, bpm, .. } = rig_of(punk.rider.as_ref());
        if rpm > 30 {
            return Err(Error::Invalid(format!(
                "icon.punk.rider.spin_rpm: {rpm} is above 30 (turns a minute; 0 = still)"
            )));
        }
        // 0 resolved to 96 above, so it passes
        if !(40..=200).contains(&bpm) {
            return Err(Error::Invalid(format!(
                "icon.punk.rider.bpm: {bpm} is outside 40-200 (beats a minute; 0 = 96)"
            )));
        }
    }
    // checked whatever the scene: a zine block with no zine item is inert, not invalid
    let spot = spot_of(p);
    if !spot.is_empty() {
        hex_rgb(spot).map_err(|e| Error::Invalid(format!("zine.spot: {e}")))?;
    }

    let check = |s: &str, field: &str| -> Result<(), Error> {
        parse_res(s)
            .map(|_| ())
            .map_err(|e| Error::Invalid(format!("{field}: {e}")))
    };
    match p.output.as_ref().and_then(|o| o.sink.as_ref()) {
        Some(output::Sink::File(f)) => check(&f.resolution, "output.file.resolution")?,
        Some(output::Sink::Stdout(s)) => check(&s.resolution, "output.stdout.resolution")?,
        Some(output::Sink::Directory(d)) => {
            for r in &d.resolutions {
                check(r, "output.directory.resolutions")?;
            }
        }
        None => {}
    }
    Ok(())
}

/// The resolution presets, in UI order. `parse_res` reads this too, so accepted == offered.
pub const RESOLUTIONS: [(&str, (u32, u32)); 8] = [
    ("1080p", (1920, 1080)),
    ("1440p", (2560, 1440)),
    ("4k", (3840, 2160)),
    ("720p", (1280, 720)),
    ("mobile", (1080, 1920)),
    ("square", (1080, 1080)),
    ("tablet", (1536, 2048)),
    ("ultrawide", (3440, 1440)),
];

/// Empty -> 1080p, else a preset name or WIDTHxHEIGHT. Zero dimensions are rejected.
pub fn parse_res(s: &str) -> Result<(u32, u32), Error> {
    // Default on the raw input, before trimming: whitespace-only is rejected, as in Python.
    let s = if s.is_empty() { "1080p" } else { s };
    let s = s.trim().to_lowercase();
    let s = s.as_str();
    if let Some((_, wh)) = RESOLUTIONS.iter().find(|(name, _)| *name == s) {
        return Ok(*wh);
    }
    let bad = || {
        let names: Vec<&str> = RESOLUTIONS.iter().map(|(n, _)| *n).collect();
        Error::Invalid(format!(
            "bad resolution '{s}': use WIDTHxHEIGHT or a preset {names:?}"
        ))
    };
    let (w, h) = s.split_once('x').ok_or_else(bad)?;
    let (w, h) = (
        w.parse::<u32>().map_err(|_| bad())?,
        h.parse::<u32>().map_err(|_| bad())?,
    );
    if w == 0 || h == 0 {
        return Err(Error::Invalid(format!(
            "bad resolution '{s}': both dimensions must be non-zero"
        )));
    }
    Ok((w, h))
}

/// One config for every distinct picture `validate` allows; both test sweeps enumerate from here.
/// A setting with no visible effect (a zine block on a blueprint page) is valid but never listed:
/// the corpus rejects two configs that render the same SVG.
/// Matrix angle and colour are non-default on purpose: defaults would skip the code they pin.
pub fn valid_configs(seed: u32) -> Vec<serde_json::Value> {
    use serde_json::json;
    let mut grounds = Vec::new();
    // Dense enums: walking until try_from fails is declaration order.
    for motion in (0..).map_while(|i| trihex::Motion::try_from(i).ok()) {
        for image in (0..).map_while(|i| trihex::Image::try_from(i).ok()) {
            if motion == trihex::Motion::Closeopen && image == trihex::Image::None {
                continue; // rejected by validate(), though renderable
            }
            grounds.push(
                json!({"trihex": {"motion": motion.as_str_name(), "image": image.as_str_name()}}),
            );
        }
    }
    grounds.push(json!({"summit": {}}));
    grounds.push(json!({"treeline": {}}));
    grounds.push(json!({"halfpipe": {}}));

    let scene = |background, icon, overlay| json!({"seed": seed, "background": background, "icon": icon, "overlay": overlay});
    let mut out = Vec::new();
    for background in &grounds {
        for icon in [
            json!({"hexatri": {"motion": "ROTATE"}}),
            json!({"hexatri": {"motion": "STATIC"}}),
            json!({"ship": {}}),
            json!({"punk": {}}),
        ] {
            for overlay in [
                json!({}),
                json!({"matrix": {"angle": 250, "color": "#395e53cc"}}),
            ] {
                out.push(scene(background.clone(), icon.clone(), overlay));
            }
        }
    }
    // Each summit setting once, on the default icon: crossing it with
    // every icon and overlay would add renders, not code paths.
    let hexatri = || json!({"hexatri": {"motion": "ROTATE"}});
    for snow in ["NO_SNOW", "BLIZZARD"] {
        out.push(scene(
            json!({"summit": {"snow": snow}}),
            hexatri(),
            json!({}),
        ));
    }
    out.push(scene(
        json!({"treeline": {"snow": "BLIZZARD"}}),
        hexatri(),
        json!({}),
    ));
    out.push(scene(
        json!({"halfpipe": {"snow": "BLIZZARD"}}),
        hexatri(),
        json!({}),
    ));
    let mut spot = scene(json!({"summit": {}}), hexatri(), json!({}));
    spot["zine"] = json!({"spot": "#22c8e5"});
    out.push(spot);
    // each rider and punk setting once, on a summit punk; reverse on a still gear, or a bpm with
    // nothing moving to it, would repeat a picture
    let rider = |rider| json!({"rider": rider});
    for punk in [
        rider(json!({"gear": "CROSSED_SKIS"})),
        rider(json!({"counter_clockwise": true})),
        rider(json!({"spin_rpm": 0})),
        rider(json!({"spin_rpm": 20})),
        rider(json!({"motion": "BOB"})),
        rider(json!({"motion": "SWAY"})),
        rider(json!({"motion": "BOB", "bpm": 150})),
        json!({"crest_wave": true}),
        json!({"rainbow_flow": true}),
        json!({"chatter": true}),
        json!({"eyes": "POP"}),
    ] {
        out.push(scene(
            json!({"summit": {}}),
            json!({"punk": punk}),
            json!({}),
        ));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_schema_rejects_what_it_cannot_represent() {
        assert!(parse(r#"{"icon":{"ship":{"motion":"ROTATE"}}}"#).is_err());
        assert!(parse(r#"{"overlay":{"angle":90}}"#).is_err());
        assert!(parse(r#"{"output":{"file":{"path":"a.svg"},"stdout":{}}}"#).is_err());
        assert!(parse(r#"{"backgrond":{}}"#).is_err());
        assert!(parse(r#"{"background":{"trihex":{"motion":"SPIRAL"}}}"#).is_err());
    }

    #[test]
    fn the_old_flat_background_is_rejected() {
        assert!(parse(r#"{"background":{"motion":"SCAN"}}"#).is_err());
    }

    #[test]
    fn an_empty_config_is_a_complete_config() {
        let p = parse("{}").expect("{} must parse");
        assert_eq!(p.seed, 0);
        assert!(matches!(
            ground_of(&p),
            Ground::Trihex {
                motion: trihex::Motion::Static,
                ..
            }
        ));
        assert!(p.icon.is_none());
        assert!(matches!(
            ground_of(
                &parse(r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}}}"#)
                    .unwrap()
            ),
            Ground::Trihex {
                motion: trihex::Motion::Closeopen,
                ..
            }
        ));
    }

    #[test]
    fn an_empty_config_resolves_to_the_old_defaults() {
        let s = resolve(&parse("{}").unwrap());
        assert_eq!(s.seed, 0);
        assert_eq!(
            s.ground,
            Ground::Trihex {
                motion: trihex::Motion::Static,
                image: trihex::Image::None,
            }
        );
        assert_eq!(s.glyph, Glyph::Hexatri { rotate: true });
        assert!(s.overlay.is_none());
        assert_eq!(s.slug(), "static-rotate-hexatri-none-none");
    }

    #[test]
    fn a_full_config_resolves_every_axis() {
        let s = resolve(
            &parse(
                r##"{"seed":7,"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}},
                    "icon":{"ship":{}},
                    "overlay":{"matrix":{"angle":250,"color":"#395e53cc"}}}"##,
            )
            .unwrap(),
        );
        assert_eq!(s.seed, 7);
        assert_eq!(s.glyph, Glyph::Ship);
        assert_eq!(s.slug(), "closeopen-static-ship-space-matrix");
        let rain = s.overlay.unwrap();
        assert_eq!(rain.angle, 250.0);
        assert_eq!(rain.color, "#395e53cc");

        let s = resolve(&parse(r#"{"overlay":{"matrix":{"angle":0}}}"#).unwrap());
        assert_eq!(
            s.overlay.unwrap().color,
            crate::blueprint::style::MATRIX_COLOR
        );

        // STATIC -> rotate:false; a swapped variant would pass every other test.
        let s = resolve(&parse(r#"{"icon":{"hexatri":{"motion":"STATIC"}}}"#).unwrap());
        assert_eq!(s.glyph, Glyph::Hexatri { rotate: false });
    }

    #[test]
    fn validate_rejects_what_the_schema_cannot() {
        for bad in [
            r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"NONE"}}}"#,
            r#"{"overlay":{"matrix":{"angle":400}}}"#,
            r#"{"overlay":{"matrix":{"angle":-1}}}"#,
            r#"{"overlay":{"matrix":{"color":"395e53"}}}"#,
            r#"{"output":{"directory":{"resolutions":["1080"]}}}"#,
            r#"{"output":{"stdout":{"resolution":"0x0"}}}"#,
        ] {
            assert!(validate(&parse(bad).unwrap()).is_err(), "accepted {bad}");
        }
        assert!(
            validate(
                &parse(r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}}}"#)
                    .unwrap()
            )
            .is_ok()
        );
    }

    #[test]
    fn spot_is_validated_and_normalised() {
        let e = validate(&parse(r##"{"zine":{"spot":"#e6394680"}}"##).unwrap())
            .unwrap_err()
            .to_string();
        assert!(e.contains("zine.spot") && e.contains("no alpha"), "{e}");
        assert!(validate(&parse(r#"{"zine":{"spot":"red"}}"#).unwrap()).is_err());
        assert_eq!(
            resolve(&parse(r##"{"zine":{"spot":" #22C8E5 "}}"##).unwrap()).spot,
            "#22c8e5"
        );
        assert_eq!(resolve(&parse("{}").unwrap()).spot, "#e63946");
    }

    #[test]
    fn an_inert_zine_block_is_accepted() {
        assert!(validate(&parse(r##"{"zine":{"spot":"#22c8e5"}}"##).unwrap()).is_ok());
    }

    #[test]
    fn a_summit_config_resolves_to_a_zine_scene() {
        let s = resolve(
            &parse(r#"{"background":{"summit":{"snow":"BLIZZARD"}},"icon":{"ship":{}}}"#).unwrap(),
        );
        assert_eq!(
            s.ground,
            Ground::Summit {
                snow: Snow::Blizzard
            }
        );
        assert!(s.uses(Mood::Zine) && s.uses(Mood::Blueprint));
        assert_eq!(s.slug(), "summit-blizzard-static-ship-none");
        let s = resolve(&parse(r#"{"background":{"summit":{}}}"#).unwrap());
        assert_eq!(s.slug(), "summit-flurry-rotate-hexatri-none");
    }

    #[test]
    fn spin_rpm_is_capped_and_zero_means_still() {
        let punk = |rider: &str| format!(r#"{{"icon":{{"punk":{{"rider":{rider}}}}}}}"#);
        let e = validate(&parse(&punk(r#"{"spin_rpm":31}"#)).unwrap())
            .unwrap_err()
            .to_string();
        assert!(e.starts_with("icon.punk.rider.spin_rpm:"), "{e}");
        assert!(validate(&parse(&punk(r#"{"spin_rpm":30}"#)).unwrap()).is_ok());
        let rig = |rider: &str| match resolve(&parse(&punk(rider)).unwrap()) {
            Scene {
                glyph: Glyph::Punk(p),
                ..
            } => p.rig,
            s => panic!("{s:?}"),
        };
        assert_eq!(rig(r#"{"spin_rpm":0}"#).rpm, 0);
        assert_eq!(rig("{}").rpm, 8);
        let s = resolve(&parse(&punk(r#"{"spin_rpm":0}"#)).unwrap());
        assert!(s.uses(Mood::Zine) && s.uses(Mood::Blueprint));
        assert_eq!(s.slug(), "static-still-punk-none-none");
    }

    #[test]
    fn bpm_out_of_range_is_rejected() {
        let punk = |bpm: u32| {
            parse(&serde_json::json!({"icon": {"punk": {"rider": {"bpm": bpm}}}}).to_string())
                .unwrap()
        };
        for bad in [39, 201] {
            let e = validate(&punk(bad)).unwrap_err().to_string();
            assert!(e.starts_with("icon.punk.rider.bpm:"), "{e}");
        }
        for ok in [0, 40, 200] {
            assert!(validate(&punk(ok)).is_ok(), "rejected {ok}");
        }
        let Glyph::Punk(p) = resolve(&punk(0)).glyph else {
            panic!("not a punk")
        };
        assert_eq!(p.rig.bpm, 96, "0 is the default tempo");
    }

    #[test]
    fn parse_res_takes_presets_and_dimensions() {
        assert_eq!(parse_res("").unwrap(), (1920, 1080));
        assert_eq!(parse_res("4K").unwrap(), (3840, 2160));
        assert_eq!(parse_res(" 1280x720 ").unwrap(), (1280, 720));
        for bad in ["1080", "1280x", "x720", "1280 x 720", "0x0", "1920x0", " "] {
            assert!(parse_res(bad).is_err(), "accepted {bad}");
        }
    }

    #[test]
    fn valid_configs_are_the_corpus() {
        let cfgs = valid_configs(0);
        assert_eq!(cfgs.len(), 96);
        assert_eq!(
            serde_json::to_string(&cfgs[0]).unwrap(),
            r#"{"background":{"trihex":{"image":"NONE","motion":"STATIC"}},"icon":{"hexatri":{"motion":"ROTATE"}},"overlay":{},"seed":0}"#
        );
        for c in &cfgs {
            let text = serde_json::to_string(c).unwrap();
            let p = parse(&text).unwrap_or_else(|e| panic!("{text}: {e}"));
            validate(&p).unwrap_or_else(|e| panic!("{text}: {e}"));
        }
    }

    #[test]
    fn resolutions_is_what_parse_res_accepts() {
        assert_eq!(RESOLUTIONS.len(), 8);
        for (name, wh) in RESOLUTIONS {
            assert_eq!(parse_res(name).unwrap(), wh, "preset {name}");
        }
        let msg = parse_res("nope").unwrap_err().to_string();
        for (name, _) in RESOLUTIONS {
            assert!(
                msg.contains(name),
                "error message omits preset {name}: {msg}"
            );
        }
    }
}
